class HideCommand(CommandStrategy):
    usage_str = 'hide <unit-type> "<unit-name>"'
    stored_units = {"alias": dict(), "slot": dict(), "intent": dict()}
    stored_variations = {"alias": dict(), "slot": dict(), "intent": dict()}
    def __init__(self, command_str, quiet=False):
        super(HideCommand, self).__init__(command_str, quiet)
        self._units_to_delete = []
        self._var_to_delete = []

    def execute_on_unit(self, unit_type, unit_name, variation_name=None):
        try:
            unit = AST.get_or_create()[unit_type][unit_name]
            if variation_name is None:
                self.stored_units[unit_type.name][unit_name] = unit
                self._units_to_delete.append((unit_type, unit_name))
                self.print_wrapper.write(
                    unit_type.name.capitalize() + " '" + unit_name + \
                    "' was successfully hidden."
                )
            else:
                if variation_name not in unit._variation_rules:
                    self.print_wrapper.error_log(
                        "Couldn't find variation '" + variation_name + \
                        "' in " + unit_type.name + " '" + unit_name + "'."
                    )
                    return
                self._var_to_delete.append((unit_type, unit_name, variation_name))
                rules = unit._variation_rules[variation_name]
                if unit_name not in self.stored_variations[unit_type.name]:
                    self.stored_variations[unit_type.name][unit_name] = \
                        {variation_name: rules}
                else:
                    self.stored_variations[unit_type.name][unit_name][variation_name] = \
                        rules
                self.print_wrapper.write(
                    "Variation '" + variation_name + "' of " + \
                    unit_type.name + " '" + unit_name + \
                    "' was successfully hidden."
                )
        except KeyError:
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was not defined."
            )

    def finish_execution(self):
        for (unit_type, unit_name) in self._units_to_delete:
            AST.get_or_create().delete_unit(unit_type, unit_name)
        self._units_to_delete = []

        for (unit_type, unit_name, variation_name) in self._var_to_delete:
            AST.get_or_create().delete_unit(
                unit_type, unit_name, variation_name
            )
        self._var_to_delete = []

class AST(Singleton):
    _instance = None
    def __init__(self):
        self._alias_definitions = dict()
        self._slot_definitions = dict()
        self._intent_definitions = dict()

        self.stats = Stats.get_or_create()


    def _get_relevant_dict(self, unit_type):
        """Returns the dict that stores units of type `unit_type`."""
        if unit_type == UnitType.alias:
            return self._alias_definitions
        elif unit_type == UnitType.slot:
            return self._slot_definitions
        elif unit_type == UnitType.intent:
            return self._intent_definitions
        else:
            raise TypeError(
                "Tried to get a definition with wrong type " + \
                "(expected alias, slot or intent)"
            )
    def __getitem__(self, unit_type):
        """
        Returns the dictionary requested.
        `unit_type` can be either a str ("alias", "slot" or "intent")
        or a `UnitType`.
        @raises: - `KeyError` if `unit_type` is an invalid str.
                 - `ValueError` if `unit_type´ is neither a str or a `UnitType`.
        """
        if isinstance(unit_type, str):
            if unit_type == UnitType.alias.value:
                unit_type = UnitType.alias
            elif unit_type == UnitType.slot.value:
                unit_type = UnitType.slot
            elif unit_type == UnitType.intent.value:
                unit_type = UnitType.intent
            else:
                raise KeyError(
                    "Invalid key for the AST: '" + unit_type + "'."
                )
        elif not isinstance(unit_type, UnitType):
            raise TypeError(
                "Invalid type of key: " + unit_type.__class__.__name__ + "."
            )
        return self._get_relevant_dict(unit_type)


    def _add_unit(self, unit_type, unit):
        """
        Adds the intent definition `intent` in the relevant dict.
        @raises: `ValueError` if the intent was already defined.
        """
        self.stats.new_variation_unit_declared(unit_type)
        relevant_dict = self._get_relevant_dict(unit_type)
        if unit.identifier in relevant_dict:
            raise ValueError(
                "Tried to declare " + unit_type.value + " '" + \
                unit.identifier + "' twice."
            )
        relevant_dict[unit.identifier] = unit
        self.stats.new_unit_declared(unit_type)

    def add_alias(self, alias):
        """
        Adds the alias definition `alias` in the relevant dict.
        @raises: `ValueError` if the alias was already defined.
        """
        # NOTE there might be a better way to check that the alias is not already defined without needing to call `get_relevant_dict`
        self._add_unit(UnitType.alias, alias)

    def add_slot(self, slot):
        """
        Adds the slot definition `slot` in the relevant dict.
        @raises: `ValueError` if the slot was already defined.
        """
        self._add_unit(UnitType.slot, slot)

    def add_intent(self, intent):
        """
        Adds the intent definition `intent` in the relevant dict.
        @raises: `ValueError` if the intent was already defined.
        """
        self._add_unit(UnitType.intent, intent)

    def add_unit(self, unit, unit_type=None):
        """
        Adds the unit definition `unit` in the relevant dict.
        If `unit_type` is `None`, detects the type of the definition
        by itself.
        @raises: - `TypeError` if the unit type is of an invalid type.
                 - `ValueError` if the unit was already declared.
        """
        if unit_type is None:
            if isinstance(unit, AliasDefinition):
                unit_type = UnitType.alias
            elif isinstance(unit, SlotDefinition):
                unit_type = UnitType.slot
            elif isinstance(unit, IntentDefinition):
                unit_type = UnitType.intent
            else:
                raise TypeError(  # Should never happen
                    "Tried to add something else than a unit definition " + \
                    "to the AST."
                )
        self._add_unit(unit_type, unit)


    def rename_unit(self, unit_type, old_name, new_name):
        """
        Changes the name of the unit `old_name` to `new_name` if it exists.
        @raises: - `KeyError` if the unit of type `unit_type` and name
                   `unit_name` wasn't declared.
                 - `ValueError` if the unit with name `new_name` already
                   existed.
        """
        relevant_dict = self._get_relevant_dict(unit_type)
        if old_name not in relevant_dict:
            raise KeyError(
                "Tried to rename " + unit_type.name + " '" + old_name + \
                "', but it wasn't declared."
            )
        if new_name in relevant_dict:
            raise ValueError(
                "Tried to rename " + unit_type.name + " '" + old_name + \
                "' to '" + new_name + "', but this " + unit_type.name + \
                " already existed."
            )
        unit = relevant_dict[old_name]
        del relevant_dict[old_name]
        unit.set_identifier(new_name)
        relevant_dict[new_name] = unit

    def delete_unit(self, unit_type, unit_name, variation_name=None):
        """
        Deletes the declared unit `unit_name` of type `unit_type`.
        If `variation_name` is not `None`, only deletes this particular
        variation for this unit.
        @raises: - `KeyError` if the unit `unit_name` wasn't declared.
                 - `KeyError` if the variation `variation_name` doesn't exist.
        """
        relevant_dict = self._get_relevant_dict(unit_type)
        if unit_name not in relevant_dict:
            raise KeyError(
                "Tried to delete " + unit_type.name + " '" + unit_name + \
                "', but it wasn't declared."
            )
        if variation_name is None:
            self.stats.one_unit_removed(unit_type)
            self.stats.several_variation_units_removed(
                unit_type, relevant_dict[unit_name].get_number_variations()
            )
            del relevant_dict[unit_name]
        else:
            relevant_dict[unit_name].delete_variation(variation_name)
            self.stats.one_variation_unit_removed(unit_type)


    def get_entities_synonyms(self):  # TODO move that into AST
        """
        Makes a dict of all the synonyms of entities
        based on the slot value they are assigned.
        """
        synonyms = dict()
        for slot_definition in self._slot_definitions:
            current_synonyms_dict = \
                self._slot_definitions[slot_definition].get_synonyms_dict()
            for slot_value in current_synonyms_dict:
                extend_list_in_dict(
                    synonyms, slot_value, current_synonyms_dict[slot_value]
                )
        return remove_duplicates(synonyms)


    def print_DBG(self):
        print("Aliases (" + str(len(self._alias_definitions)) + "):")
        for alias_name in self._alias_definitions:
            self._alias_definitions[alias_name].print_DBG()
        print("Slots (" + str(len(self._slot_definitions)) + "):")
        for slot_name in self._slot_definitions:
            self._slot_definitions[slot_name].print_DBG()
        print("Intents (" + str(len(self._intent_definitions)) + "):")
        for intent_name in self._intent_definitions:
            self._intent_definitions[intent_name].print_DBG()
        print()

class CommandStrategy(object):
    usage_str = "Undefined"  # Should be overriden by subclasses
    def __init__(self, command_str, quiet=False):
        self.command_tokens = CommandStrategy.tokenize(command_str)

        redirection_tuple = \
                CommandStrategy.find_redirection_file_path(self.command_tokens)
        if redirection_tuple is not None:
            self.remove_redirection_tokens()
            (redirection_type, redirection_filepath) = redirection_tuple
            self.print_wrapper = \
                TerminalWriter(redirection_type, redirection_filepath)
        elif quiet:
            self.print_wrapper = \
                TerminalWriter(redirection_type=RedirectionType.quiet)
        else:
            self.print_wrapper = TerminalWriter(None)

        self._is_regex_global = None

    @staticmethod
    def tokenize(command_str):
        """Tokenizes a string that is a command."""
        splitted = command_str.split()
        if len(splitted) == 0:
            return []
        if len(splitted) == 1:
            return [splitted[0]]
        tokens = []
        current_token = ""
        inside_token = False
        inside_regex = False
        for word in splitted:
            if inside_token:
                current_token += ' ' + word
                if word.endswith('"') and (len(word) < 2 or word[-2] != '\\'):
                    inside_token = False
                    tokens.append(current_token.rstrip())
                    current_token = ""
            elif inside_regex:
                current_token += ' ' + word
                if CommandStrategy._is_end_regex(word):
                    inside_regex = False
                    tokens.append(current_token)
                    current_token = ""
            elif (
                word.startswith('"') and word.endswith('"')
                and (len(word) < 2 or word[-2] != '\\')
            ):
                tokens.append(word)
            elif word.startswith('"'):
                inside_token = True
                current_token += word
            elif word.startswith("/") and CommandStrategy._is_end_regex(word):
                tokens.append(word)
            elif word.startswith("/"):
                inside_regex = True
                current_token += word
            else:  # not inside a token and not starting with "
                tokens.append(word)
        if current_token != "":
            tokens.append(current_token.rstrip())
        return tokens
    @staticmethod
    def _is_end_regex(word):
        """Returns `True` if `word` is the end of a regex."""
        return \
            word.endswith("/") or word.endswith("/g") \
            or word.endswith("/i") or word.endswith("/ig") \
            or word.endswith("/gi")

    @staticmethod
    def find_redirection_file_path(tokens):
        """
        Finds the path of the file
        which the output of a command should be redirected to and
        returns it along with the type of redirection that it is (in a 2-tuple).
        The type of redirection is an enumeration item of type
        `RedirectionType`.
        Returns `None` if no redirection was found.
        Returns `(RedirectionType.quiet, None)` if a redirection should be done
        to nowhere.
        (This can be achieved by using the redirections symbols and providing
        no filepath).
        """
        if len(tokens) < 2:
            return None
        if tokens[-2] == REDIRECTION_APPEND_SYM:
            return (RedirectionType.append, tokens[-1])
        if tokens[-2] == REDIRECTION_SYM:
            return (RedirectionType.truncate, tokens[-1])
        if (
            tokens[-1] == REDIRECTION_APPEND_SYM
            or tokens[-1] == REDIRECTION_SYM
        ):
            return (RedirectionType.quiet, None)
        return None

    @staticmethod
    def get_unit_type_from_str(unit_type_str):
        """
        Transforms the string `unit_type_str`
        into the corresponding `UnitType` value.
        Returns `None` if there exist no corresponding `UnitType` value.
        """
        from chatette.utils import UnitType
        from chatette.parsing.utils import INTENT_SYM
        from chatette.parsing.utils import ALIAS_SYM
        from chatette.parsing.utils import SLOT_SYM
        unit_type_str = unit_type_str.lower()
        if unit_type_str in ("alias", ALIAS_SYM):
            return UnitType.alias
        if unit_type_str in ("slot", SLOT_SYM):
            return UnitType.slot
        if unit_type_str in ("intent", INTENT_SYM):
            return UnitType.intent
        return None


    @staticmethod
    def remove_quotes(text):
        """
        Removes the double quotes at the beginning and end of `text` and
        returns it. Double quotes that shouldn't be considered are escaped.
        """
        return text[1:-1].replace(ESCAPEMENT_SYM + '"', '"')

    @staticmethod
    def split_exact_unit_name(text):
        """
        Removes the double quotes at the beginning and end of `text` and
        splits `text` into a unit name and a variation identifier.
        Those two parts are separated in `text` by a hashtag `#` (unescaped).
        Returns a list with both those str inside it or the unit name and
        `None` for the variation identifier if it wasn't found.
        @raises: - `SyntaxError` if `text` is not valid (several hashtags),
        """
        no_quote_text = text[1:-1].replace(ESCAPEMENT_SYM + '"', '"')
        splitted = no_quote_text.split(VARIATION_SYM)
        processed_splitted = []
        current_word = ""
        for word in splitted:
            if word.endswith(ESCAPEMENT_SYM):
                if current_word == "":
                    current_word = word[:-1]
                else:
                    current_word += VARIATION_SYM + word[:-1]
            elif current_word == "":
                processed_splitted.append(word)
            else:
                processed_splitted.append(current_word + VARIATION_SYM + word)
                current_word = ""
        if len(processed_splitted) > 2:
            raise SyntaxError("Too many hashtags in unit identifier.")
        if len(processed_splitted) == 1:
            return [processed_splitted[0], None]
        return processed_splitted


    def get_regex_name(self, name):
        """
        If a regex is used within `name`,
        returns a compiled regex that is able to find all units with a name
        that matches some pattern.
        Returns `None` otherwise.
        """
        if (
            name.startswith(REGEX_SYM)
            and (
                name.endswith(REGEX_SYM)
                or name[-2] == REGEX_SYM
                or name[-3] == REGEX_SYM)
        ):
            splitted_str = [e for e in name.split(REGEX_SYM) if e != ""]
            if len(splitted_str) == 1:
                return re.compile(name[1:-1].replace('\\'+REGEX_SYM, REGEX_SYM))

            flags = splitted_str[-1]
            text_without_flags = rchop(name, flags)
            self._is_regex_global = 'g' in flags
            if 'i' in flags:
                return re.compile(
                    text_without_flags[1:-1].replace(
                        '\\'+REGEX_SYM, REGEX_SYM
                    ),
                    re.IGNORECASE
                )
            return re.compile(
                text_without_flags[1:-1].replace('\\'+REGEX_SYM, REGEX_SYM)
            )
        return None

    def next_matching_unit_name(self, unit_type, regex):
        """
        Yields the next unit name of type `unit_type`
        whose name matches `regex`.
        """
        relevant_dict = AST.get_or_create()._get_relevant_dict(unit_type)
        if self._is_regex_global:
            for unit_name in relevant_dict:
                if regex.search(unit_name):
                    yield unit_name
        else:
            for unit_name in relevant_dict:
                if regex.match(unit_name):
                    yield unit_name
    def get_all_matching_unit_names(self, unit_type, regex):
        """
        Returns a list of unit names of type `unit_type`
        whose name matches `regex`.
        NOTE: this is used with 'delete' command since the generator that
              returns the same data cannot be used in that case (dict changes
              size during iteration).
        """
        relevant_dict = AST.get_or_create()[unit_type]
        if self._is_regex_global:
            return [name for name in relevant_dict if regex.search(name)]
        return [name for name in relevant_dict if regex.match(name)]

    def remove_redirection_tokens(self):
        """
        Removes the tokens that represent a redirection
        from `self.command_tokens`.
        @pre: There are redirection tokens in the tokens.
        """
        if (
            self.command_tokens[-2] == REDIRECTION_APPEND_SYM
            or self.command_tokens[-2] == REDIRECTION_SYM
        ):
            self.command_tokens = self.command_tokens[:-2]
        else:
            self.command_tokens = self.command_tokens[:-1]


    def flush_output(self):
        """
        Asks the wrapper of print to flush its outputs
        to the redirected file (if such a file exists).
        """
        self.print_wrapper.flush()


    def should_exit(self):
        """
        Returns `True` if the program should exit the interactive mode.
        This method should be overriden by subclasses.
        """
        return False

    def execute(self):
        """
        Executes the whole command represented by this object.
        This method can be overriden by subclasses if a different algorithm is
        required.
        """
        # TODO support variations
        if len(self.command_tokens) < 3:
            self.print_wrapper.error_log(
                "Missing some arguments\nUsage: " + self.usage_str
            )
            return

        unit_type = CommandStrategy.get_unit_type_from_str(self.command_tokens[1])
        if unit_type is None:
            self.print_wrapper.error_log(
                "Unknown unit type: '" + str(self.command_tokens[1]) + "'."
            )
            return

        unit_regex = self.get_regex_name(self.command_tokens[2])
        if unit_regex is None:
            try:
                [unit_name, variation_name] = \
                    CommandStrategy.split_exact_unit_name(
                        self.command_tokens[2]
                    )
            except SyntaxError:
                self.print_wrapper.error_log(
                    "Unit identifier couldn't be interpreted. " + \
                    "Did you mean to escape some hashtags '#'?")
                return
            self.execute_on_unit(unit_type, unit_name, variation_name)
        else:
            count = 0
            for unit_name in self.next_matching_unit_name(
                unit_type, unit_regex
            ):
                self.execute_on_unit(unit_type, unit_name)
                count += 1
            if count == 0:
                self.print_wrapper.write("No " + unit_type.name + " matched.")
        self.finish_execution()

    def execute_on_unit(self, unit_type, unit_name, variation_name=None):
        """
        Executes the command on a specific unit.
        This method HAS to be overriden by subclasses if they don't override
        `execute`.
        """
        raise NotImplementedError()

    def finish_execution(self):
        """
        This function is executed at the end of the command and
        can be overriden to implement things such as cleaning up or changing
        the size of dictionaries and list that were being iterated over.
        NOTE: it is called no matter what happened before (the command worked
              or failed).
        """
        pass

def execute_on_unit(self, unit_type, unit_name, variation_name=None):
    if variation_name is None:
        try:
            unit = HideCommand.stored_units[unit_type.name][unit_name]
            AST.get_or_create().add_unit(unit, unit_type)
            del HideCommand.stored_units[unit_type.name][unit_name]
            self.print_wrapper.write(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was successfully restored."
            )
        except KeyError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' was not previously hidden."
            )
        except ValueError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' is already defined in the parser."
            )
    else:
        try:
            unit = AST.get_or_create()[unit_type][unit_name]
        except KeyError:
            self.print_wrapper.error_log(
                unit_type.name.capitalize() + " '" + unit_name + \
                "' is not defined."
            )
            return
        try:
            rules = \
                HideCommand.stored_variations[unit_type.name][unit_name][variation_name]
            if variation_name in unit._variation_rules:
                self.print_wrapper.error_log(
                    "Variation '" + variation_name + \
                    "' is already defined for " + unit_type.name + \
                    " '" + unit_name + "'."
                )
                return
            unit.add_all_rules(rules, variation_name)
            self.print_wrapper.write(
                "Variation '" + variation_name + "' of " + \
                unit_type.name + " '" + unit_name + \
                "' was successfully restored."
            )
        except KeyError:
            self.print_wrapper.error_log(
                "Variation '" + variation_name + \
                "' of " + unit_type.name + " '" + unit_name + \
                "' was not previously hidden."
            )
